```php
<?php
require "connexion.php";   // objet PDO $pdo

$des   = trim($_POST["designation"] ?? "");
$prix  = filter_var($_POST["prix"] ?? "", FILTER_VALIDATE_FLOAT);
$stock = filter_var($_POST["stock"] ?? "", FILTER_VALIDATE_INT);

if ($des === "" || $prix === false || $stock === false) {
    exit("Données invalides.");
}
$req = $pdo->prepare("INSERT INTO produit (designation, prix, stock) VALUES (?, ?, ?)");
$req->execute([$des, $prix, $stock]);
echo "Produit ajouté, numéro " . htmlspecialchars($pdo->lastInsertId());
```

```php
<?php
require "connexion.php";
$produits = $pdo->query("SELECT id_produit, designation, prix, stock FROM produit ORDER BY designation");
echo "<table border='1'><tr><th>N°</th><th>Désignation</th><th>Prix</th><th>Stock</th></tr>";
foreach ($produits as $p) {
    echo "<tr><td>" . $p["id_produit"] . "</td>"
       . "<td>" . htmlspecialchars($p["designation"]) . "</td>"
       . "<td>" . $p["prix"] . "</td>"
       . "<td>" . $p["stock"] . "</td></tr>";
}
echo "</table>";
```

```php
<?php
require "connexion.php";
$motcle = trim($_GET["motcle"] ?? "");
$req = $pdo->prepare("SELECT designation, prix FROM produit WHERE designation LIKE ? ORDER BY prix");
$req->execute(["%" . $motcle . "%"]);
$lignes = $req->fetchAll(PDO::FETCH_ASSOC);

echo count($lignes) . " résultat(s)<ul>";
foreach ($lignes as $l) {
    echo "<li>" . htmlspecialchars($l["designation"]) . " — " . $l["prix"] . " F</li>";
}
echo "</ul>";
```

Le formulaire de recherche utilise `method="get"` et un champ `name="motcle"`.
